import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number,
  quantity: number = 1,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([makeLine("a", 500)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(9.99)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart below threshold", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100)], 4999)).toBe(799);
    });

    it("returns 0 when subtotal equals freeOverCents", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOverCents", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100)], 10000)).toBe(0);
    });

    it("returns flat fee when no threshold is set", () => {
      const calc = new FlatShippingCalculator(999);
      expect(calc.computeShippingCents([makeLine("a", 100)], 99999)).toBe(999);
    });

    it("returns 0 for empty cart even with no threshold", () => {
      const calc = new FlatShippingCalculator(999);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 for empty cart below threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow();
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: 10.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 2 },
      ];
      expect(calc.computeShippingCents(lines, 200)).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 400)], 1000)).toBe(300);
    });

    it("selects first bracket at exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 500)], 1000)).toBe(300);
    });

    it("selects second bracket above first boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 501)], 1000)).toBe(600);
    });

    it("selects second bracket at its boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 2000)], 1000)).toBe(600);
    });

    it("selects third bracket above second boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 2001)], 1000)).toBe(1200);
    });

    it("uses heaviest bracket cost as overflow when no overflowCostCents", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 10000)], 1000)).toBe(1200);
    });

    it("uses explicit overflowCostCents when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      expect(calc.computeShippingCents([makeLine("a", 10000)], 1000)).toBe(2000);
    });

    it("sums weight across multiple lines with quantity", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 2 items × 300g = 600g → second bracket (600)
      expect(
        calc.computeShippingCents([makeLine("a", 300, 2)], 1000),
      ).toBe(600);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 600 },
      ];
      const calc = new WeightBasedShippingCalculator(unordered);
      expect(calc.computeShippingCents([makeLine("a", 400)], 1000)).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { Product, CartLine } from "../src/product.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2500 };

describe("Cart - line management", () => {
  it("adds a product with quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("merges quantity when adding the same product again", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(4);
  });

  it("throws for non-positive quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("throws for negative unit price on add", () => {
    const cart = new Cart();
    const bad: Product = { id: "x", name: "X", unitPriceCents: -100 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the product", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("unknown", 5)).toThrow();
  });

  it("updateQuantity throws for negative quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const snap = cart.snapshot();
    (snap as CartLine[])[0]!.quantity = 99;
    expect(cart.itemCount).toBe(1);
  });
});

describe("Cart - totals pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2500
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4500);
  });

  it("applies discount policy on the subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 5); // subtotal 5000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(500);
    expect(discount.computeDiscountCents).toHaveBeenCalledWith(5000);
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 99999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(productA, 1); // subtotal 1000
    expect(cart.totals().discountCents).toBe(1000);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(productA, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("computes tax on the discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 200,
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax, region: "US-CA" });
    cart.add(productA, 1); // subtotal 1000, discount 200, taxable 800
    const totals = cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
    expect(totals.taxCents).toBe(80);
  });

  it("computes shipping on lines and discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 300,
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(productA, 2); // subtotal 2000, discount 300, discounted 1700
    const totals = cart.totals();
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      1700,
    );
    expect(totals.shippingCents).toBe(599);
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 100 };
    const tax: TaxCalculator = { computeTaxCents: () => 50 };
    const shipping: ShippingCalculator = {
      computeShippingCents: () => 200,
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(productA, 1); // subtotal 1000
    const totals = cart.totals();
    // discounted = 1000 - 100 = 900; total = 900 + 50 + 200 = 1150
    expect(totals.totalCents).toBe(1150);
  });

  it("defaults to NoDiscount, NoTax, FreeShipping, US region", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(1000);
  });

  it("empty cart totals all zeros", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = { computeTaxCents: () => -100 };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: () => -50,
    };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

