describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects an empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow();
    });
  });

  describe("sum mode", () => {
    it("sums discounts from each child using the original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 5000 = 500, fixed 200 → sum = 700
      expect(composite.computeDiscountCents(5000)).toBe(700);
    });

    it("can exceed subtotal (clamped later by Cart)", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(80), new PercentageDiscountPolicy(80)],
        "sum",
      );
      // 80% + 80% of 1000 = 800 + 800 = 1600 > 1000
      expect(composite.computeDiscountCents(1000)).toBe(1600);
    });

    it("returns 0 when subtotal is zero", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 when subtotal is negative", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativePolicy = {
        computeDiscountCents: () => -100,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(300)],
        "sum",
      );
      // -100 clamped to 0, + 300 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies each discount to the remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 1000 = 100, remaining 900
      // Second: 10% of 900 = 90
      // Total discount = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("order matters in chain mode", () => {
      const bigFirst = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(50)],
        "chain",
      );
      const smallFirst = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // bigFirst: fixed 500 from 1000 → remaining 500, then 50% of 500 = 250, total = 750
      expect(bigFirst.computeDiscountCents(1000)).toBe(750);
      // smallFirst: 50% of 1000 = 500, remaining 500, then fixed min(500,500) = 500, total = 1000
      expect(smallFirst.computeDiscountCents(1000)).toBe(1000);
    });

    it("cannot discount below zero remaining", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new FixedAmountDiscountPolicy(800)],
        "chain",
      );
      // First: min(800, 1000) = 800, remaining 200
      // Second: min(800, 200) = 200, remaining 0
      // Total = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 when subtotal is zero", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ]);
      // sum: 100 + 200 = 300
      expect(composite.computeDiscountCents(5000)).toBe(300);
    });
  });
});
