import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };

describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("uses refreshed prices from priceFetcher", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };

      const result = await cart.checkout({ priceFetcher: fetcher });
      // refreshed price: 1500 * 2 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    });

    it("propagates priceFetcher errors", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };

      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        "price service down",
      );
    });

    it("skips refresh when no priceFetcher is given", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const result = await cart.checkout({});
      expect(result.totals.subtotalCents).toBe(1000);
    });
  });

  describe("inventory check", () => {
    it("proceeds when all items are available", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(checker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(2);
      }
    });

    it("throws InventoryError on partial-stock denial (available: true but qty insufficient)", async () => {
      const cart = new Cart();
      cart.add(productA, 10);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(10);
        expect(invErr.available).toBe(3);
      }
    });

    it("checks items in order and stops on first denial", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);

      const checker: InventoryChecker = {
        check: vi.fn().mockImplementation((id: string) => {
          if (id === "a") return Promise.resolve({ available: false });
          return Promise.resolve({ available: true });
        }),
      };

      await expect(cart.checkout({ inventoryChecker: checker })).rejects.toThrow(
        InventoryError,
      );
      // Only the first item should have been checked
      expect(checker.check).toHaveBeenCalledTimes(1);
    });
  });

  describe("async tax provider", () => {
    it("uses asyncTaxProvider for tax computation", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(productA, 1); // subtotal 1000

      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider: provider });
      expect(provider.getRate).toHaveBeenCalledWith("US-CA");
      expect(result.totals.taxCents).toBe(100);
    });

    it("propagates asyncTaxProvider rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service error")),
      };

      await expect(cart.checkout({ asyncTaxProvider: provider })).rejects.toThrow(
        "tax service error",
      );
    });

    it("applies discount before async tax calculation", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        region: "US",
      });
      cart.add(productA, 10); // subtotal 10000, discount 2000, taxable 8000

      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider: provider });
      expect(result.totals.discountCents).toBe(2000);
      expect(result.totals.taxCents).toBe(800); // 10% of 8000
    });
  });

  describe("full pipeline composition", () => {
    it("combines price refresh + inventory + async tax + discount + shipping", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "FR",
      });
      cart.add(productA, 2); // original subtotal 2000

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const taxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.2),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider: taxProvider,
      });

      // Refreshed: 1200 * 2 = 2400 subtotal
      expect(result.totals.subtotalCents).toBe(2400);
      // Discount: 10% of 2400 = 240
      expect(result.totals.discountCents).toBe(240);
      // Taxable: 2400 - 240 = 2160, tax = 20% of 2160 = 432
      expect(result.totals.taxCents).toBe(432);
      // Shipping: flat 500 (subtotal 2160 < no threshold)
      expect(result.totals.shippingCents).toBe(500);
      // Total: 2160 + 432 + 500 = 3092
      expect(result.totals.totalCents).toBe(3092);
    });

    it("checkout with no collaborators uses sync path", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.totalCents).toBe(1000);
    });
  });
});
"}

